165	class BTree {
166	    private BTreeNode root;
167	    private final int minimumDegree;
168	
169	    public BTree(int minimumDegree) {
170	        this.root = null;
171	        this.minimumDegree = minimumDegree;
172	    }
173	
174	    String traversal() {
175	        StringBuilder traversal = new StringBuilder();
176	        if (!isEmpty()) {
177	            root.appendTraversal(traversal);
178	        }
179	        return traversal.toString();
180	    }
181	
182	    void traverse() {
183	        System.out.print(traversal());
184	    }
185	
186	    BTreeNode search(int key) {
187	        return isEmpty() ? null : root.search(key);
188	    }
189	
190	    boolean contains(int key) {
191	        return search(key) != null;
192	    }
193	
194	    void insertAll(int[] keys) {
195	        for (int key : keys) {
196	            insert(key);
197	        }
198	    }
199	
200	    void insert(int key) {
201	        if (isEmpty()) {
202	            createRoot(key);
203	            return;
204	        }
205	
206	        if (root.isFull()) {
207	            splitRootAndInsert(key);
208	            return;
209	        }
210	
211	        root.insertNonFull(key);
212	    }
213	
214	    private boolean isEmpty() {
215	        return root == null;
216	    }
217	
218	    private void createRoot(int key) {
219	        root = new BTreeNode(minimumDegree, true);
220	        root.initializeWithSingleKey(key);
221	    }
222	
223	    private void splitRootAndInsert(int key) {
224	        BTreeNode newRoot = new BTreeNode(minimumDegree, false);
225	        newRoot.setChild(0, root);
226	        newRoot.splitChild(0, root);
227	        newRoot.insertAfterRootSplit(key);
228	        root = newRoot;
229	    }
230	}
